+package com.example.contact;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+final class MessageStore {
+
+    private static final String SESSION_KEY = MessageStore.class.getName();
+
+    private MessageStore() {
+    }
+
+    static void add(ContactMessage message) {
+        messages().addFirst(message);
+    }
+
+    static List<ContactMessage> getMessages() {
+        return List.copyOf(messages());
+    }
+
+    @SuppressWarnings("unchecked")
+    private static List<ContactMessage> messages() {
+        VaadinSession session = VaadinSession.getCurrent();
+        List<ContactMessage> messages = (List<ContactMessage>) session
+                .getAttribute(SESSION_KEY);
+        if (messages == null) {
+            messages = new ArrayList<>();
+            session.setAttribute(SESSION_KEY, messages);
+        }
+        return messages;
+    }
+}
