+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void completeContactFlow() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("About", find(RouterLink.class).single().getText());
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextField phone = find(TextField.class).withLabel("Phone").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+        Grid<?> grid = find(Grid.class).single();
+
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertEquals("Name is required", name.getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number",
+                email.getErrorMessage());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertEquals(0, test(grid).size());
+        assertFalse(find(Notification.class).exists());
+
+        test(name).setValue("Alice");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+        test(send).click();
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals(0, test(grid).size());
+
+        test(email).setValue("");
+        test(phone).setValue("555-0100");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertEquals("Message must be at most 500 characters",
+                message.getErrorMessage());
+
+        test(message).setValue("First message");
+        test(send).click();
+        assertEquals(1, test(grid).size());
+        assertEquals("Alice", test(grid).getCellText(0, 0));
+        assertEquals("First message", test(grid).getCellText(0, 1));
+        assertEquals("Message sent",
+                test(find(Notification.class).single()).getText());
+        assertTrue(name.isEmpty());
+        assertTrue(email.isEmpty());
+        assertTrue(phone.isEmpty());
+        assertTrue(message.isEmpty());
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Bob");
+        assertTrue(send.isEnabled());
+        test(phone).setValue("555-0101");
+        test(message).setValue("Second message");
+        fireShortcut(Key.ENTER);
+        assertEquals(2, test(grid).size());
+        assertEquals("Bob", test(grid).getCellText(0, 0));
+
+        navigate(AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+        navigate(ContactView.class);
+        assertEquals(2, test(find(Grid.class).single()).size());
+
+        name = find(TextField.class).withLabel("Name").single();
+        test(name).setValue("Draft");
+        test(find(RouterLink.class).single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Draft", name.getValue());
+        assertTrue(find(Dialog.class).exists());
+
+        test(find(Button.class).withText("Keep editing").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Draft", name.getValue());
+
+        test(find(RouterLink.class).single()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
